# Breakdown by source for select
import collections
for split in ['select']:
    rows = [json.loads(l) for l in open(f'/practice/original/{split}.jsonl')]
    by_src = collections.defaultdict(list)
    for r in rows:
        by_src[r['source']].append(r)
    for s, rs in by_src.items():
        acc = sum(r['correct'] for r in rs)/len(rs)
        cut = sum(1 for r in rs if r['finish']=='length')/len(rs)
        print(split, s, len(rs), 'acc', round(acc,3), 'cut', round(cut,3))
# index levels for select qids
idx = {}
for line in open('/practice/index.tsv'):
    parts = line.rstrip('\n').split('\t')
    idx[parts[0]] = parts[1:]
sel = [json.loads(l) for l in open('/practice/original/select.jsonl')]
by_level = collections.defaultdict(list)
for r in sel:
    by_level[idx[r['qid']][1]].append(r)
for lv, rs in sorted(by_level.items()):
    print(lv, len(rs), 'acc', round(sum(r['correct'] for r in rs)/len(rs),3), 'cut', round(sum(1 for r in rs if r['finish']=='length')/len(rs),3))

