# Pick short correct vs short incorrect finished generations with boxed answers
texts_correct, texts_wrong = [], []
for fn in ['/work/gen_5_original.jsonl', '/work/gen_12_original.jsonl', '/work/gen_13_original.jsonl', '/work/gen_14_original.jsonl']:
    for l in open(fn):
        r = json.loads(l)
        if r['finish'] == 'stop' and '\\boxed' in r['text']:
            if r['correct']: texts_correct.append(r['text'])
            else: texts_wrong.append(r['text'])
print('correct pool', len(texts_correct), 'wrong pool', len(texts_wrong))
# choose short ones (fewer tokens)
def ntok(t): return len(tok.encode(t).ids)
correct_short = sorted(texts_correct, key=ntok)[:8]
wrong_short = sorted(texts_wrong, key=ntok)[:8]
for r in correct_short + wrong_short:
    print(ntok(r), 'C' if r in correct_short else 'W', r['text'][:80].replace('\n',' '))

# Final decision: no candidate shows a robust positive effect; drop all edits (submit starting weights)
for L in range(24):
    try:
        drop_edit(f'model.language_model.layers.{L}.mlp.down_proj.weight')
    except Exception as ex:
        print('already dropped', L)
print('edits in /work/edited:', edited())

