    for l in open(fn):
        r = json.loads(l)
        if r['correct'] and r['finish']=='stop' and '\\boxed' in r['text']:
            pool.append(r['text'])
def ntok(t): return len(tok.encode(t).ids)
pool = [t for t in pool if ntok(t) < 1500]
pool.sort(key=ntok)
