for t in mathpool[:6]:
    print(ntok(t), repr(t[:90].replace('\n',' ')))

# Build the 10 short correct texts for teacher-forced measurement of conclude positions
pool = []
for fn in ['/work/gen_5_original.jsonl']:
    for l in open(fn):
        r = json.loads(l)
        if r['correct'] and r['finish']=='stop' and '\\boxed' in r['text'] and ntok(r['text'])<400:
            pool.append(r['text'])
